UPDATE `EMAIL_SCENARIO` SET `SUBJECT`='Alert !! This is to Notify that {{EditSpocContact.LoginUser}} @{{EditSpocContact.LoginOrgName}} changed the Point of contact for the {{EditSpocContact.changedOwnerOrg}} to {{EditSpocContact.OwnerName}}', `BODY`='Dear {{EditSpocContact.ClientFirstName}} {{EditSpocContact.ClientLastName}} @{{EditSpocContact.changedOwnerOrg}},\n\n{{EditSpocContact.LoginUser}} @{{EditSpocContact.LoginOrgName}} has changed the point of contact from {{EditSpocContact.changedOwnerName}} to {{EditSpocContact.OwnerName}}( {{EditSpocContact.ownerEmail}} ).So your future communication will be done through this contact.\nIf you do not wish to change this please ignore this email. if you want to approve this change please click Confirm.',`SIGNATURE`='Thank you\nSource Lead Support' WHERE `UNIQUE_SCENARIO_NAME`='Edit SpocContact' and `ENTITY_TYPE`='Email';

