UPDATE `EMAIL_SCENARIO` SET `SUBJECT`='Interview scheduled for the {{InterviewerInvitation.RequirementTitle}} job', `BODY`='Dear Member,\n \n  Interview scheduled on the {{InterviewerInvitation.InterviewDate}} for the job.\n \n  Job name : {{InterviewerInvitation.RequirementTitle}}\n  Interview date : {{InterviewerInvitation.InterviewDate}}\n  Details : {{InterviewerInvitation.Details}}\n  Interview Type : {{InterviewerInvitation.InterviewType}}\n  Applicants : {{InterviewerInvitation.ApplicantName}} \n \n  For clear details login into the system.' WHERE `UNIQUE_SCENARIO_NAME`='Interviewer Invitation' and `ENTITY_TYPE`='Email';

UPDATE `EMAIL_SCENARIO` SET `BODY`='Welcome !!!\n Dear {{ProfessionalInvitation.professionalName}}\n\n It is great to see that you have started accessing \n User Name : {{ProfessionalInvitation.loginUserName}}\n Your Sourcelead URL : {{ProfessionalInvitation.resetLink}}\n I hope you will have a wonderful time with  If you have any questions or comments, feel free to reach out to us at info@com' WHERE `UNIQUE_SCENARIO_NAME`='Professional Invitation' and `ENTITY_TYPE`='Email';

UPDATE `EMAIL_SCENARIO` SET `SUBJECT`='{{InviteUser.FirstName}} Invited to SourceLead', `BODY`='Dear {{InviteUser.FirstName}},\n\nYou have been invited to SourceLead as a {{InviteUser.Role}}.\nYou can simply login into SourceLead by clicking below link with following credentials\n\nUsername : {{InviteUser.UserEmailId}} \nPassword  : {{InviteUser.Password}}\n\n {{InviteUser.LoginURL}}' WHERE `UNIQUE_SCENARIO_NAME`='Invite User' and `ENTITY_TYPE`='Email';

UPDATE `EMAIL_SCENARIO` SET `SIGNATURE`='Best Regards,\n{{RejectedMailAboutTheRequirement.loginUserName}}\n{{RejectedMailAboutTheRequirement.role}}', `BODY`='Dear {{RejectedMailAboutTheRequirement.jobInitiatorName}},\n\n{{RejectedMailAboutTheRequirement.approverName}} rejected the Job {{RejectedMailAboutTheRequirement.requirementId-Name}}.\n<b>Reason:</b>\n{{RejectedMailAboutTheRequirement.reason}}\nPlease login to check more details\n\n{{RejectedMailAboutTheRequirement.link}}' WHERE `UNIQUE_SCENARIO_NAME`='Rejected Mail About The Requirement' and `ENTITY_TYPE`='Email';

UPDATE `EMAIL_SCENARIO` SET `SIGNATURE`='Thanks & Regards\n{{InvoiceAcceptMailtoVendor.LoginUser}},\n{{InvoiceAcceptMailtoVendor.orgName}}', `SUBJECT`='{{InvoiceAcceptMailtoVendor.invoiceID}} Accomplished by {{InvoiceAcceptMailtoVendor.orgName}}', `BODY`='Dear {{InvoiceAcceptMailtoVendor.clientorVendorName}},\n\nWe are happy to inform you that {{InvoiceAcceptMailtoVendor.invoiceID}} Accomplished successfully. the brief bill details\nBill Date : {{InvoiceAcceptMailtoVendor.date}}\nAmount: {{InvoiceAcceptMailtoVendor.totalAmount}}\nDue Date: {{InvoiceAcceptMailtoVendor.dueDate}}\nPlease contact us if you have any queries or concerns\n{{InvoiceAcceptMailtoVendor.loginLink}}' WHERE `UNIQUE_SCENARIO_NAME`='InvoiceAcceptMailtoClient' and `ENTITY_TYPE`='Email';

