UPDATE `EMAIL_SCENARIO` SET `SIGNATURE`='Thanks & Regards\n{{InvoiceRejectMailtoVendor.LoginUser}},\n{{InvoiceRejectMailtoVendor.orgName}}', `SUBJECT`='{{InvoiceRejectMailtoVendor.invoiceID}} got Rejected', `BODY`='Dear {{InvoiceRejectMailtoVendor.clientorVendorName}},\n\nWe have received invoice statement {{InvoiceRejectMailtoVendor.invoiceID}} and in the amount of {{InvoiceRejectMailtoVendor.totalAmount}} we believe this invoice statement {{InvoiceRejectMailtoVendor.invoiceID}} to be incorrect because\nReason: {{InvoiceRejectMailtoVendor.reason}}\nPlease contact us if you have any queries or concerns.\n{{InvoiceRejectMailtoVendor.loginLink}}' WHERE `UNIQUE_SCENARIO_NAME`='InvoiceRejectMailtoVendor' and `ENTITY_TYPE`='Email';

